CREATE OR REPLACE FUNCTION public.enforce_bay_check_leaf_store_area()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM store_areas
    WHERE id = NEW.store_area_id
      AND organization_id = NEW.organization_id
      AND parent_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'bay_checks.store_area_id must reference a leaf bay in the same organization';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM check_cycles
    WHERE id = NEW.cycle_id
      AND organization_id = NEW.organization_id
  ) THEN
    RAISE EXCEPTION 'bay_checks.cycle_id must reference a cycle in the same organization';
  END IF;

  RETURN NEW;
END;
$function$
